static Config loadConfig(const fs::path&root){Config c;c.root=root;auto p=root/folder/L"settings.ini";c.id=get(p,L"id");c.device=get(p,L"device");c.host=get(p,L"host",c.host);c.user=get(p,L"user",c.user);c.fingerprint=get(p,L"fingerprint");c.port=int(number(get(p,L"port"),22));c.hours=int(number(get(p,L"hours"),24));c.keep=int(number(get(p,L"keep")));c.automatic=get(p,L"automatic",L"1")==L"1";int n=int(number(get(p,L"path_count")));if(n>0&&n<=100){c.paths.clear();for(int i=0;i<n;++i)c.paths.push_back(get(p,L"path"+std::to_wstring(i)));}return c;}
