static W xml(W s){for(auto p:{std::make_pair(W(L"&"),W(L"&amp;")),{L"<",L"&lt;"},{L">",L"&gt;"},{L"\"",L"&quot;"}}){size_t i=0;while((i=s.find(p.first,i))!=W::npos){s.replace(i,p.first.size(),p.second);i+=p.second.size();}}return s;}
static W currentSID(){HANDLE token=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))throw std::runtime_error("User token unavailable");DWORD n=0;GetTokenInformation(token,TokenUser,nullptr,0,&n);std::vector<char>b(n);if(!GetTokenInformation(token,TokenUser,b.data(),n,&n)){CloseHandle(token);throw std::runtime_error("User SID unavailable");}CloseHandle(token);LPWSTR value=nullptr;if(!ConvertSidToStringSidW(((TOKEN_USER*)b.data())->User.Sid,&value))throw std::runtime_error("SID conversion failed");W sid=value;LocalFree(value);return sid;}
static void schedule(bool enable){if(!enable){process(L"schtasks.exe /Delete /TN "+quote(taskName)+L" /F");return;}SYSTEMTIME st;GetLocalTime(&st);wchar_t date[64];swprintf_s(date,L"%04u-%02u-%02uT%02u:%02u:%02u",st.wYear,st.wMonth,st.wDay,st.wHour,st.wMinute,st.wSecond);
 W task=L"<?xml version=\"1.0\" encoding=\"UTF-16\"?><Task version=\"1.2\" xmlns=\"http://schemas.microsoft.com/windows/2004/02/mit/task\"><RegistrationInfo><Description>DroBinG backup: user-enabled, USB identity checked, 24-hour persisted deadline.</Description></RegistrationInfo><Triggers><LogonTrigger><Enabled>true</Enabled><UserId>"+currentSID()+L"</UserId><Delay>PT30S</Delay></LogonTrigger><TimeTrigger><Repetition><Interval>PT15M</Interval><StopAtDurationEnd>false</StopAtDurationEnd></Repetition><StartBoundary>"+W(date)+L"</StartBoundary><Enabled>true</Enabled></TimeTrigger></Triggers><Principals><Principal id=\"User\"><UserId>"+currentSID()+L"</UserId><LogonType>InteractiveToken</LogonType><RunLevel>LeastPrivilege</RunLevel></Principal></Principals><Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><StartWhenAvailable>true</StartWhenAvailable><Enabled>true</Enabled><ExecutionTimeLimit>PT4H</ExecutionTimeLimit></Settings><Actions Context=\"User\"><Exec><Command>"+xml((localDir()/L"DroBinGBackup.exe").wstring())+L"</Command><Arguments>--scheduled</Arguments><WorkingDirectory>"+xml(localDir().wstring())+L"</WorkingDirectory></Exec></Actions></Task>";
 auto p=localDir()/L"task.xml";std::ofstream f(p,std::ios::binary|std::ios::trunc);wchar_t bom=0xfeff;f.write((char*)&bom,2);f.write((char*)task.data(),task.size()*2);f.close();if(process(L"schtasks.exe /Create /TN "+quote(taskName)+L" /XML "+quote(p.wstring())+L" /F"))throw std::runtime_error("Task registration failed; run settings as administrator if Windows policy requires it");}
