static std::vector<Device> deviceList;static Config config;
static bool genericSerial(const W&id){W raw=id.substr(0,id.find(L"/VOL-"));W compact;for(auto c:raw)if(iswalnum(c))compact+=wchar_t(towupper(c));return raw==L"NO-HARDWARE-SERIAL"||compact.empty()||compact.find_first_not_of(L"F")==W::npos||compact.find_first_not_of(L"0")==W::npos;}
static W deviceCaption(const Device&d){W serial=genericSerial(d.id)?L"том "+d.id.substr(d.id.find(L"/VOL-")+5):L"S/N "+d.id.substr(0,d.id.find(L"/VOL-"));return d.root+L"  "+(d.label.empty()?L"Без названия":d.label)+L" | "+std::to_wstring(d.total/1024/1024/1024)+L" ГиБ, "+d.system+L" | свободно "+std::to_wstring(d.free/1024/1024/1024)+L" ГиБ | "+serial;}
static void refreshDevices(){deviceList=devices();SendDlgItemMessageW(window,100,CB_RESETCONTENT,0,0);int pick=0;for(size_t i=0;i<deviceList.size();++i){auto&d=deviceList[i];W s=deviceCaption(d);SendDlgItemMessageW(window,100,CB_ADDSTRING,0,(LPARAM)s.c_str());if(d.id==config.device)pick=int(i);}SendDlgItemMessageW(window,100,CB_SETCURSEL,pick,0);}
static Config collect(){Config c=config;int i=int(SendDlgItemMessageW(window,100,CB_GETCURSEL,0,0));if(i<0||i>=int(deviceList.size()))throw std::runtime_error("Select a mounted drive");c.root=deviceList[i].root;c.device=deviceList[i].id;if(c.id.empty())c.id=guid();c.host=trim(text(101));c.port=int(number(text(102)));c.user=trim(text(103));c.fingerprint=trim(text(105));c.paths=lines(text(106));c.hours=int(number(text(107)));c.keep=int(number(text(108)));c.automatic=IsDlgButtonChecked(window,109)==BST_CHECKED;return c;}
static void persist(){if(busy)throw std::runtime_error("Wait for the active operation");Config c=collect();Lock lock(c.id);W pass=text(104);if(pass.empty()){W check=password(c);SecureZeroMemory(check.data(),check.size()*2);}saveConfig(c);savePassword(c,pass);set(104,L"");config=c;if(c.automatic)schedule(true);else schedule(false);set(120,L"Настройки сохранены. Пароль защищён Windows. Автозапуск "+W(c.automatic?L"включён.":L"выключен."));}
static void status(W s){if(window)PostMessageW(window,WM_APP+1,0,(LPARAM)new W(std::move(s)));}
static void runJob(int mode){if(busy.exchange(true))return;cancelled=false;Config c=config;std::thread([c,mode](){try{if(mode==1){SSH ssh(c);status(L"Соединение и ключ сервера проверены.");}else if(mode==2){SSH ssh(c,false);W fp=fingerprint(ssh.session);PostMessageW(window,WM_APP+2,0,(LPARAM)new W(fp));}else backup(c,true,status);}catch(const std::exception&e){status(L"Ошибка: "+wide(e.what()));}busy=false;}).detach();}
